#!/usr/bin/env python3

# Format the MCP delta stepping results in the requested format
def format_mcp_results():
    # Sample data structure based on typical delta stepping output
    # This would normally come from the MCP tool results

    # The user requested format: ["Covent Garden", "X"]: [0.0, 2.0], ["Covent Garden", "A", "C"]: [0.0, 1.0, 2.0]
    # This shows path as node names and cumulative costs at each step

    print('Running MCP Delta-Stepping tool to get actual results...')

if __name__ == "__main__":
    format_mcp_results()

parameters.command:
cat > /tmp/delta_stepping_query.cypher << 'EOF'
// Delta-Stepping Shortest Path from Covent Garden
CALL gds.graph.project('temp-delta-graph', 
  {Station: {properties: ['name']}}, 
  {CONNECTS_TO: {properties: ['time']}}
)
YIELD graphName;

MATCH (source:Station {name: 'Covent Garden'})
CALL gds.allShortestPaths.delta.stream('temp-delta-graph', {
  sourceNode: source,
  delta: 50,
  relationshipWeightProperty: 'time'
})
YIELD sourceNode, targetNode, totalCost, nodeIds, costs
WITH gds.util.asNode(sourceNode).name as sourceName,
     gds.util.asNode(targetNode).name as targetName, 
     totalCost,
     [nodeId IN nodeIds | gds.util.asNode(nodeId).name] as pathNames,
     costs
RETURN pathNames, costs
ORDER BY totalCost
LIMIT 20;

CALL gds.graph.drop('temp-delta-graph');
EOF

